{"implementation": "def solve(case):
    edges = case['edges']
    communities = case['communities']
    resolution = case['resolution']
    degree = {}
    for u, v, w in edges:
        degree[u] = degree.get(u, 0) + w
        degree[v] = degree.get(v, 0) + w
    total_weight = sum(w for _,_,w in edges)
    if total_weight == 0:
        return 0.0
    internal = {}
    for u, v, w in edges:
        cu = communities[u]
        cv = communities[v]
        if cu == cv:
            internal[cu] = internal.get(cu, 0) + w
    sum_deg = {}
    for node, comp in communities.items():
        sum_deg[comp] = sum_deg.get(comp, 0) + degree.get(node, 0)
    two_m = 2 * total_weight
    q = 0.0
    for comp in internal:
        q += internal[comp] - resolution * (sum_deg[comp] ** 2) / two_m
    q /= two_m
    return {"modularity": q}"}
